Method.Implementation:
Set tStatus = $$$OK
Try {
	If $IsObject(..RecordX) {
		Set tStatus = ##class(IHC.ITF.DStruc.ShKeyWordRecXLIN).PutObject(pIOStream,..RecordX,0)
		If $$$ISERR(tStatus) Quit
	}
	If $IsObject(..RecordLINU) {
		Set tStatus = ##class(IHC.ITF.DStruc.ShKeyWordRecU).PutObject(pIOStream,..RecordLINU,0)
		If $$$ISERR(tStatus) Quit
	}
	If $IsObject(..RecordO) {
		Set tStatus = ##class(IHC.ITF.DStruc.ShKeyWordRecO).PutObject(pIOStream,..RecordO,0)
		If $$$ISERR(tStatus) Quit
	}
	If $IsObject(..RecordCDSD) {
		Set tStatus = ##class(IHC.ITF.DStruc.ShKeyWordRecCDSD837I).PutObject(pIOStream,..RecordCDSD,0)
		If $$$ISERR(tStatus) Quit
	}
	Set seqKey = ""
	For {
		Set tElement = ..RecordCDCC.GetNext(.seqKey)
		If (seqKey = "") Quit
		If $IsObject(tElement) {
			Set tStatus = tElement.PutSequence(pIOStream)
			If $$$ISERR(tStatus) Quit
		}
		Set tStatus = ..RecordCDCC.%UnSwizzleAt(seqKey)
		If $$$ISERR(tStatus) Quit
	}
	If $$$ISERR(tStatus) Quit
}
Catch {
	Set tStatus = $$$SystemError
}
Quit tStatus

Set tStatus = $$$OK
Try {
	Set tId = ..%Id()
	If ""=tId {
		Set seqKey = ""
		For {
			Set tElement = ..RecordCDCC.GetNext(.seqKey)
			If (seqKey = "") Quit
			If $IsObject(tElement) && (""'=tElement.%Id()) {
				Set tElementId = tElement.%Id()
				Set tStatus = ##class(IHC.ITF.DStruc.Record.KeyWord837I.RecordCDCC).%DeleteId(tElementId)
			}
			If $$$ISERR(tStatus) Quit
		}
	}
} Catch ex {
	Set tStatus = $$$SystemError
}
Quit tStatus
